'use client';
import {useState,useEffect,createContext,useContext,FormEvent,ReactNode} from 'react';
import Link from 'next/link';
import {usePathname,useRouter,useSearchParams} from 'next/navigation';
import {ArrowUpRight,ArrowRight,ArrowLeft,ChevronRight,ChevronLeft,Search,MapPin,Menu,X,Heart,Building2,House,LandPlot,BedDouble,Maximize,ShieldCheck,Handshake,KeyRound,Compass,Plus,Phone,MessageCircle,Check,CheckCircle2,SlidersHorizontal,Grid2X2,Images,TreePine,Dumbbell,Waves,Car,Users,TrainFront,BriefcaseBusiness,School,Clock,Mail,MoveUpRight,Pause,Play} from 'lucide-react';
import {Tabs,TabsList,TabsTrigger,TabsContent} from '@/components/ui/tabs';
import {Dialog,DialogContent,DialogTitle,DialogDescription} from '@/components/ui/dialog';
import {Sheet,SheetContent,SheetTitle,SheetDescription} from '@/components/ui/sheet';
import {Select,SelectTrigger,SelectValue,SelectContent,SelectItem} from '@/components/ui/select';
import {Slider} from '@/components/ui/slider';
import {Checkbox} from '@/components/ui/checkbox';
import {RadioGroup,RadioGroupItem} from '@/components/ui/radio-group';
import {Toaster,toast} from 'sonner';
import {PropertyTools} from './webmcp';
import {properties,localities,steps,Property,price,img} from './data';
